<main class="scroll withnav community-page">
<section class="utility-hero"><div><span class="pm-kicker">M13 · Community</span><h1>Pune Community</h1><p>Neighbourhood updates, questions and recommendations. Community submissions are moderated before publication and are not newsroom reporting.</p></div></section>
<?php if($areas): ?><nav class="utility-filters"><a class="chip <?=!$selectedArea?'active':''?>" href="<?=pm_e(pm_url('/community'))?>">All Pune</a><?php foreach($areas as $area): ?><a class="chip <?=$selectedArea===$area?'active':''?>" href="<?=pm_e(pm_url('/community?area='.rawurlencode($area)))?>"><?=pm_e($area)?></a><?php endforeach; ?></nav><?php endif; ?>
<section class="admin-panel" style="margin:16px"><h2>Share with your neighbourhood</h2><form data-community-form class="admin-form"><label>Type<select name="type"><?php foreach($types as $type): ?><option value="<?=pm_e($type)?>"><?=pm_e(ucfirst($type))?></option><?php endforeach; ?></select></label><label>Area<input name="area" required value="<?=pm_e($selectedArea?:($areas[0]??''))?>" placeholder="Baner"></label><label>Title<input name="title" required maxlength="140"></label><label>Details<textarea name="body" required maxlength="3000"></textarea></label><button class="btn" type="submit">Submit for review</button><span data-community-status></span></form></section>
<section class="utility-feed"><?php if(!$posts): ?><div class="empty"><b>No published community posts here yet.</b><span>New submissions appear after moderation.</span></div><?php endif; ?><?php foreach($posts as $post): ?><article class="utility-card"><div class="utility-card-head"><span class="utility-kind"><?=pm_e(strtoupper($post['type']))?></span><span>Community · moderated</span></div><h2><?=pm_e($post['title'])?></h2><p><?=pm_e($post['body'])?></p><div class="utility-meta"><span><?=pm_e($post['area'])?></span></div><button class="act" data-community-report="<?=pm_e($post['id'])?>" type="button">Report</button></article><?php endforeach; ?></section>
</main>
